<?php
declare(strict_types=1);
namespace InaudisVote\Services;
use InaudisVote\Core\Audit;use InaudisVote\Core\Database;use PDO;
final class WitnessService{
 public static function assign(int $electionId,int $userId,int $by):void{$pdo=Database::connection();$q=$pdo->prepare("SELECT COUNT(*) FROM users u JOIN elections e ON e.organization_id=u.organization_id WHERE u.id=:uid AND u.role='witness' AND u.status='active' AND e.id=:eid");$q->execute(['uid'=>$userId,'eid'=>$electionId]);if(!(int)$q->fetchColumn())throw new \InvalidArgumentException('El Ministro de Fe debe estar activo y pertenecer a la organización de la votación.');$s=$pdo->prepare('INSERT IGNORE INTO election_witnesses(election_id,user_id,assigned_by) VALUES(:eid,:uid,:by)');$s->execute(['eid'=>$electionId,'uid'=>$userId,'by'=>$by]);Audit::log('witness.assigned','election',$electionId,['witness_user_id'=>$userId],$by);}
 public static function isAssigned(int $electionId,int $userId):bool{$s=Database::connection()->prepare('SELECT COUNT(*) FROM election_witnesses WHERE election_id=:eid AND user_id=:uid');$s->execute(['eid'=>$electionId,'uid'=>$userId]);return (bool)$s->fetchColumn();}
 public static function forElection(int $electionId):array{$s=Database::connection()->prepare("SELECT u.id,u.name,u.email,ew.assigned_at FROM election_witnesses ew JOIN users u ON u.id=ew.user_id WHERE ew.election_id=:id ORDER BY ew.assigned_at");$s->execute(['id'=>$electionId]);return $s->fetchAll(PDO::FETCH_ASSOC);}
 public static function available(int $organizationId):array{$s=Database::connection()->prepare("SELECT id,name,email FROM users WHERE organization_id=:org AND role='witness' AND status='active' ORDER BY name");$s->execute(['org'=>$organizationId]);return $s->fetchAll(PDO::FETCH_ASSOC);}
 public static function checkpoint(int $electionId,string $stage,int $userId):string{if(!self::isAssigned($electionId,$userId))throw new \RuntimeException('No estás asignado como Ministro de Fe de este proceso.');if(!in_array($stage,['setup_reviewed','census_verified','opening_attested','closing_attested','results_attested'],true))throw new \InvalidArgumentException('Hito inválido.');$e=ElectionService::find($electionId);if(!$e)throw new \RuntimeException('Votación no encontrada.');$pdo=Database::connection();$counts=$pdo->prepare('SELECT COUNT(*) total,SUM(status="eligible") eligible,SUM(has_voted=1) voted FROM census_members WHERE election_id=:id');$counts->execute(['id'=>$electionId]);$snapshot=['election_id'=>$electionId,'stage'=>$stage,'status'=>$e['status'],'ballot_locked_at'=>$e['ballot_locked_at'],'census_locked_at'=>$e['census_locked_at'],'census'=>$counts->fetch(PDO::FETCH_ASSOC),'questions'=>ElectionService::questions($electionId),'at'=>gmdate('c')];if($stage==='results_attested')$snapshot['results']=ResultService::summary($electionId);$json=json_encode($snapshot,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRESERVE_ZERO_FRACTION);$hash=hash('sha256',(string)$json);$s=$pdo->prepare('INSERT INTO witness_checkpoints(election_id,user_id,stage,snapshot_json,sha256_hash) VALUES(:eid,:uid,:stage,:json,:hash)');$s->execute(['eid'=>$electionId,'uid'=>$userId,'stage'=>$stage,'json'=>$json,'hash'=>$hash]);Audit::log('witness.checkpoint','election',$electionId,['stage'=>$stage,'sha256'=>$hash],$userId);return $hash;}
 public static function checkpoints(int $electionId):array{$s=Database::connection()->prepare('SELECT wc.*,u.name user_name FROM witness_checkpoints wc JOIN users u ON u.id=wc.user_id WHERE wc.election_id=:id ORDER BY wc.created_at DESC');$s->execute(['id'=>$electionId]);return $s->fetchAll(PDO::FETCH_ASSOC);}
}